+
+        for (var clause : booleanQuery.clauses()) {
+            assertEquals(BooleanClause.Occur.SHOULD, clause.getOccur());
+            assertThat(clause.getQuery(), either(instanceOf(featureQueryClass)).or(instanceOf(boostQueryClass)));
+        }
+    }
