+
+        TestCandidateAwareClient(
+            ClientYamlSuiteRestSpec restSpec,
+            RestClient restClient,
+            List<HttpHost> hosts,
+            Version esVersion,
+            Version masterVersion,
+            String os,
+            CheckedSupplier<RestClientBuilder, IOException> clientBuilderWithSniffedNodes
