+                attribute.getAttributeValues().add(stringValue);
+            });
+            attributeStatement.getAttributes().add(attribute);
+        });
+        assertion.getAttributeStatements().add(attributeStatement);
+
+        response.getAssertions().add(assertion);
+
+        return response;
+    }
+
